const b = $input.first().json.body || $input.first().json;

if (!b.siteId) throw new Error('Missing required field: siteId');
if (!b.message) throw new Error('Missing required field: message');

const msg = b.message.toLowerCase().trim();
const actionWords = /\b(implement|create|add|build|make|fix|update|change|edit|delete|remove|install|modify|replace|refactor|style|redesign|adjust|set|configure|enable|disable|write|code)\b/;
const questionWords = /^(what|why|how|can you|could you|should|is it|explain|describe|tell me)/;
const isQuestion = questionWords.test(msg);
const isActionIntent = actionWords.test(msg) && !isQuestion;

// Get executionId from n8n
const executionId = $execution.id;

const executorMode = b.executorMode || 'auto';

return [{
  json: {
    siteId: b.siteId,
    conversationId: b.conversationId || null,
    userId: b.userId || 'anon',
    message: b.message.trim(),
    requestId: 'req_' + Date.now() + '_' + Math.random().toString(36).substr(2, 9),
    executionId: executionId, // Add executionId
    image: b.image || null,
    images: b.images || (b.image ? [b.image] : []),
    executorMode: executorMode,
    isActionIntent,
    isQuestion
  }
}];

// Register execution with orchestrator for stop functionality
const ctx = $input.item.json;
const requestId = ctx.requestId;
const executionId = ctx.executionId;

if (!requestId || !executionId) {
  console.log('⚠️ Missing requestId or executionId, skipping registration');
  return [{ json: ctx }];
}

try {
  console.log(`📝 Registering execution ${executionId} for request ${requestId}...`);

  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://preview-orchestrator.fly.dev/execution/register',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ 
      requestId, 
      executionId 
    }),
    timeout: 5000,
    ignoreHttpStatusErrors: true
  });

  console.log(`✅ Registered execution ${executionId}`);
} catch (e) {
  console.error('❌ Failed to register execution:', e.message);
  // Continue anyway - registration is optional
}

return [{ json: ctx }];

const inp = $('Validate & Detect Intent').item.json;
const rawSite = $input.first().json;

let site = Array.isArray(rawSite) ? rawSite[0] : (rawSite?.id ? rawSite : rawSite?.data?.[0]);
if (!site?.id) throw new Error('Site not found for siteId: ' + inp.siteId);

const SYSTEM_GITHUB_TOKEN = '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';
let githubToken = (site.access_token && site.access_token.trim()) || SYSTEM_GITHUB_TOKEN;

const siteKey = site.site_key || inp.siteId;
const repoMatch = (site.repo_url || '').match(/github\.com\/([^/]+)\/([^/]+)/);
if (!repoMatch) throw new Error('Invalid GitHub repo URL');

const owner = repoMatch[1];
const repo = repoMatch[2].replace(/\.git$/, '');
const branch = site.default_branch || 'main';
const msg = inp.message.toLowerCase();

const isCreation = /\b(create|add|new|design|generate|build|make a page)\b/i.test(msg);
const isStrictlySimple = !isCreation && /^(change|update|replace|set|fix)\s+(?!the\s+layout).{5,50}\s+(to|with|into)\s+/i.test(inp.message);
const isSimple = !isCreation && (isStrictlySimple || /^(change|update|fix)\s+(the\s+)?(title|name|text|color|heading)/i.test(inp.message));

const maxFiles = isStrictlySimple ? 1 : (isSimple ? 2 : 4);
console.log('Request type:', isSimple ? 'SIMPLE' : 'COMPLEX', '- fetching', maxFiles, 'files');

let allFiles = [];
try {
  const tree = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api.github.com/repos/' + owner + '/' + repo + '/git/trees/' + branch + '?recursive=1',
    headers: { 'Authorization': 'Bearer ' + githubToken },
    timeout: 10000
  });
  allFiles = (tree.tree || []).filter(f => f.type === 'blob' && /\.(tsx?|jsx?)$/.test(f.path) && !f.path.includes('node_modules') && f.size < 30000);
} catch (e) {}

const scored = allFiles.map(f => {
  let score = 0;
  const p = f.path.toLowerCase();
  if (p.includes('page.tsx')) score += 10;
  if (p.includes('layout')) score += 1;
  if (msg.includes('layout') || msg.includes('title') || msg.includes('metadata')) score += 10;
  if (p.includes('header')) score += 4;
  if (p.includes('footer')) score += 3;
  if (p.includes('src/app/')) score += 2;
  for (const w of msg.split(/\s+/).filter(w => w.length > 3)) {
    if (p.includes(w)) score += 20;
  }
  return { path: f.path, score };
}).sort((a, b) => b.score - a.score);

const filesToFetch = scored.slice(0, maxFiles).map(f => f.path);

return [{
  json: {
    ...inp,
    site: { id: siteKey, uuid: site.id, name: site.name || 'Unknown', repo_url: site.repo_url, branch },
    owner, repo, branch,
    previewUrl: 'https://' + siteKey + '.preview.automatelb.com',
    filesToFetch,
    isSimpleRequest: isSimple,
    isComplex: !isSimple,
    fileContents: {},
    contextFiles: [],
    executorMode: inp.executorMode || 'auto',
    githubToken
  }
}];

const ctx = $('Build Context').item.json;
const files = ctx.filesToFetch || [];
if (files.length === 0) return [{ json: { ...ctx, fileContents: {}, contextFiles: [] } }];

const contentLimit = ctx.isSimpleRequest ? 1500 : 2500;
console.log('Fetching', files.length, 'files, limit:', contentLimit, 'chars/file');

const results = await Promise.all(files.map(async (file) => {
  try {
    const response = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.github.com/repos/' + ctx.owner + '/' + ctx.repo + '/contents/' + file + '?ref=' + ctx.branch,
      headers: { 'Authorization': 'Bearer ' + ctx.githubToken, 'Accept': 'application/vnd.github.v3.raw' },
      timeout: 8000
    });
    return { path: file, content: typeof response === 'string' ? response : '', success: true };
  } catch (e) {
    return { path: file, success: false };
  }
}));

const fileContents = {};
const contextFiles = [];
for (const r of results.filter(r => r.success && r.content)) {
  fileContents[r.path] = r.content.length > contentLimit ? r.content.substring(0, contentLimit) + '...' : r.content;
  contextFiles.push(r.path);
}

return [{ json: { ...ctx, fileContents, contextFiles, _parallelFetch: true } }];

const items = $input.all();
const firstItem = items[0]?.json;

if (firstItem?._parallelFetch || firstItem?.fileContents) {
  const filesInContext = Object.keys(firstItem.fileContents || {});
  if (filesInContext.length > 0) {
    firstItem._filesInContextWarning = '🔥 CRITICAL: These ' + filesInContext.length + ' files are ALREADY LOADED in your context. DO NOT call read_file for: ' + filesInContext.join(', ');
  }
  return [{ json: firstItem }];
}

const prepItems = $('Prepare Fetch').all();
const ctx = prepItems[0]?.json?._ctx || prepItems[0]?.json || firstItem;
if (!ctx) return [{ json: { error: 'Lost context', fileContents: {}, contextFiles: [] } }];

const fileContents = ctx.fileContents || {};
const contextFiles = ctx.contextFiles || [];

for (let i = 0; i < items.length; i++) {
  const item = items[i].json;
  const path = prepItems[i]?.json?.currentFile || item.path;
  if (!path || fileContents[path]) continue;
  if (item.content) {
    try {
      const decoded = Buffer.from(item.content, 'base64').toString('utf8');
      fileContents[path] = decoded.length > 3000 ? decoded.substring(0, 3000) + '\n// ...truncated' : decoded;
      contextFiles.push(path);
    } catch (e) {}
  }
}

const filesInContext = Object.keys(fileContents);
if (filesInContext.length > 0) {
  ctx._filesInContextWarning = '🔥 CRITICAL: These ' + filesInContext.length + ' files are ALREADY LOADED. DO NOT call read_file for: ' + filesInContext.join(', ');
}

return [{ json: { ...ctx, fileContents, contextFiles } }];

