// HTTP-BASED COMPLEX EXECUTOR V9 - WITH STOP CHECK
const ctx = $input.item.json;
const requestId = ctx.requestId;
const ANTHROPIC_KEY = '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';
const MODEL = 'claude-sonnet-4-5-20250929';

const TOOLS = [
    { name: 'write_file', description: 'Write complete file. REQUIRED: path AND content must both be provided.', input_schema: { type: 'object', properties: { path: { type: 'string', description: 'File path' }, content: { type: 'string', description: 'REQUIRED: Full file content to write' } }, required: ['path', 'content'] } },
    { name: 'str_replace', description: 'Replace text in file. Best for small changes.', input_schema: { type: 'object', properties: { file: { type: 'string' }, old_text: { type: 'string' }, new_text: { type: 'string' } }, required: ['file', 'old_text', 'new_text'] } },
    { name: 'list_files', description: 'List dir', input_schema: { type: 'object', properties: { dir: { type: 'string' } }, required: ['dir'] } },
    { name: 'read_file', description: 'Read file', input_schema: { type: 'object', properties: { path: { type: 'string' } }, required: ['path'] } },
    { name: 'generate_image', description: 'Generate AI image. Returns URL to use in img src.', input_schema: { type: 'object', properties: { prompt: { type: 'string', description: 'Detailed image prompt' } }, required: ['prompt'] } },
    { name: 'search_image', description: 'Search for real images from the web (faster than generation). Returns URL.', input_schema: { type: 'object', properties: { keywords: { type: 'string', description: 'Keywords to search for' } }, required: ['keywords'] } }
];

const SYSTEM = 'You are a code editor. CRITICAL: The FILES section below contains all project code ALREADY LOADED. DO NOT ask for files. Use str_replace for small text changes. Use write_file only when you need to rewrite entire file - ALWAYS include the full content. Use search_image for real photos (faster), or generate_image for specific AI scenes. Returns URL. Complete in 1-3 tool calls. Output requirements: 1) NO markdown lists or bold text (**). 2) Max 2 sentences. 3) Focus only on independent actions (e.g. Created landing page). Reply purely in plain text. Be direct, factual, and strictly minimize tokens.';

let consecutiveErrors = 0;

// CHECK IF EXECUTION SHOULD STOP
const checkShouldStop = async () => {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://preview-orchestrator.fly.dev/execution/check/' + requestId,
      timeout: 2000,
      ignoreHttpStatusErrors: true
    });
    if (r && r.shouldStop) {
      console.log('🛑 Stop signal received from orchestrator');
      return true;
    }
  } catch (e) {
    // Ignore errors checking stop status
  }
  return false;
};

const executeTool = async (name, input) => {
    const siteId = ctx.site?.id;
    const githubToken = ctx.githubToken;
    if (!siteId) return 'FATAL: No siteId';

    if (name === 'write_file') {
        if (!input.content) {
            return 'ERROR: write_file requires content parameter. You must provide the full file content.';
        }
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/write', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.path, content: input.content, githubToken }), timeout: 20000, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true });
            if (r.statusCode >= 400) { consecutiveErrors++; return 'ERROR: ' + JSON.stringify(r.body || r.statusCode); }
            consecutiveErrors = 0;
            return JSON.stringify({ success: true, file: input.path, action: 'created' });
        } catch (e) { consecutiveErrors++; return 'ERROR: ' + e.message; }
    }

    if (name === 'str_replace') {
        if (!input.old_text || !input.new_text) {
            return 'ERROR: str_replace requires old_text and new_text parameters';
        }
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/replace', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.file, search: input.old_text, replace: input.new_text, githubToken }), timeout: 15000, json: true, ignoreHttpStatusErrors: true, returnFullResponse: true });
            if (r.statusCode >= 400) { consecutiveErrors++; return 'ERROR: ' + JSON.stringify(r.body || r.statusCode); }
            consecutiveErrors = 0;
            return JSON.stringify({ success: true, file: input.file, action: 'replaced' });
        } catch (e) { consecutiveErrors++; return 'ERROR: ' + e.message; }
    }

    if (name === 'list_files') {
        try {
            const r = await this.helpers.httpRequest({ method: 'GET', url: 'https://api.github.com/repos/' + ctx.owner + '/' + ctx.repo + '/contents/' + (input.dir || 'src') + '?ref=' + ctx.branch, headers: { 'Authorization': 'Bearer ' + githubToken }, timeout: 10000, json: true });
            return Array.isArray(r) ? r.map(f => f.path).join('\n') : 'Error';
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    if (name === 'read_file') {
        if (ctx.fileContents?.[input.path]) return ctx.fileContents[input.path].slice(0, 3000);
        try {
            const r = await this.helpers.httpRequest({ method: 'POST', url: 'https://preview-orchestrator.fly.dev/preview/read', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ siteId, filePath: input.path, githubToken }), timeout: 10000, json: true });
            return (r.content || '').slice(0, 3000);
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    if (name === 'generate_image') {
        if (!input.prompt) return 'ERROR: generate_image requires prompt parameter';
        try {
            const url = 'https://image.pollinations.ai/prompt/' + encodeURIComponent(input.prompt) + '?width=800&height=600&nologo=true';
            return JSON.stringify({ success: true, imageUrl: url, usage: 'Use this URL in img src attribute' });
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    if (name === 'search_image') {
        if (!input.keywords) return 'ERROR: search_image requires keywords parameter';
        try {
            const lock = Math.floor(Math.random() * 1000);
            const url = 'https://loremflickr.com/800/600/' + encodeURIComponent(input.keywords) + '?lock=' + lock;
            return JSON.stringify({ success: true, imageUrl: url, usage: 'Use this URL in img src attribute' });
        } catch (e) { return 'ERROR: ' + e.message; }
    }

    return 'Unknown tool';
};

const callClaude = async (msgs) => {
    try {
        const response = await this.helpers.httpRequest({ 
            method: 'POST', 
            url: 'https://api.anthropic.com/v1/messages', 
            headers: { 
                'x-api-key': ANTHROPIC_KEY, 
                'anthropic-version': '2023-06-01', 
                'content-type': 'application/json' 
            }, 
            body: JSON.stringify({ model: MODEL, max_tokens: 8192, system: SYSTEM, tools: TOOLS, messages: msgs }), 
            timeout: 120000, 
            json: true,
            ignoreHttpStatusErrors: true,
            returnFullResponse: true
        });
        if (response.statusCode >= 400) {
            console.error('Anthropic API error:', response.statusCode, JSON.stringify(response.body));
            return { error: response.body?.error?.message || response.body || response.statusCode };
        }
        return response.body;
    } catch (e) {
        console.error('Anthropic request failed:', e.message);
        return { error: e.message };
    }
};

const fileCtx = Object.entries(ctx.fileContents || {}).slice(0, 3).map(([f, c]) => f + ':\n' + c.slice(0, 2000)).join('\n---\n');
const memCtx = ctx.memoryContext ? '\nHISTORY:' + ctx.memoryContext : '';
const baseMsg = ctx.message + memCtx;
const fullMsg = baseMsg + (fileCtx ? '\n\nFILES:\n' + fileCtx : '');
const messages = [{ role: 'user', content: fullMsg }];

let output = ''; let steps = []; let i = 0;

while (i++ < 8) {
    // CHECK FOR STOP SIGNAL BEFORE EACH ITERATION
    if (await checkShouldStop()) {
        output = '🛑 Stopped by user';
        break;
    }

    if (consecutiveErrors >= 2) { output = 'Stopped: too many errors.'; break; }
    const r = await callClaude(messages);
    if (r.error) { output = 'Error: ' + JSON.stringify(r.error); break; }
    if (r.usage) console.log('Tokens:', r.usage.input_tokens, 'out:', r.usage.output_tokens);

    const toolCalls = (r.content || []).filter(c => c.type === 'tool_use');

    if (toolCalls.length === 0) {
        output = r.content?.find(c => c.type === 'text')?.text || 'Done';
        break;
    }

    const toolResults = [];
    let hasFatal = false;

    for (const tool of toolCalls) {
        const result = await executeTool(tool.name, tool.input);
        steps.push({ tool: tool.name, input: tool.input, result: result.slice(0, 150) });
        toolResults.push({ type: 'tool_result', tool_use_id: tool.id, content: result });

        if (result.startsWith('FATAL:')) {
            output = result;
            hasFatal = true;
            break;
        }
    }

    if (hasFatal) break;

    messages.push({ role: 'assistant', content: r.content });
    messages.push({ role: 'user', content: toolResults });

    if (messages[0].content.length > baseMsg.length) { messages[0].content = baseMsg + '\n(files pruned)'; }
}

return [{ json: { ...ctx, output, intermediateSteps: steps, iterations: i } }];

const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
const conversationId = ctx.conversationId || null;

if (!siteId) {
  console.log('No site UUID found, skipping memory save');
  return [{ json: ctx }];
}

const files = [...(ctx.filesModified || []), ...(ctx.filesCreated || [])].slice(0, 3);
const fileStr = files.length > 0 ? ' [' + files.join(', ') + ']' : '';

let compressedSummary = '';
const fullSummary = ctx.plan?.humanSummary || '';
if (fullSummary) {
  const firstSentence = fullSummary.match(/^[^.!?]*[.!?]/);
  compressedSummary = firstSentence ? firstSentence[0] : fullSummary.substring(0, 100);
}

const memoryEntry = {
  project_id: siteId,
  session_id: conversationId,
  memory_type: 'conversation',
  content: (ctx.message || '').substring(0, 100) + ' → ' + compressedSummary.substring(0, 150) + fileStr,
  content_json: {
    message: (ctx.message || '').substring(0, 150),
    summary: compressedSummary,
    filesModified: (ctx.filesModified || []).slice(0, 5),
    filesCreated: (ctx.filesCreated || []).slice(0, 5),
    filesDeleted: (ctx.filesDeleted || []).slice(0, 5),
    toolsUsed: [...new Set(ctx.toolsUsed || [])].slice(0, 5),
    iterations: ctx.iterations || 0,
    requestId: ctx.requestId || null,
    wasSimple: ctx.isComplex === false
  }
};

try {
  await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://jjrbnjubjiswvxeradzw.supabase.co/rest/v1/agent_memory',
    headers: {
      'apikey': 'eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Authorization': 'Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJpc3MiOiJzdXBhYmFzZSIsInJlZiI6ImpqcmJuanViamlzd3Z4ZXJhZHp3Iiwicm9sZSI6InNlcnZpY2Vfcm9sZSIsImlhdCI6MTc2NjIzMzg1OSwiZXhwIjoyMDgxODA5ODU5fQ.DDff_1lJpQo4vdnKm84-1H8QYD0diD-n7pK7VIliNe4',
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: JSON.stringify(memoryEntry),
    timeout: 10000
  });
  console.log('Memory saved (compressed) for session ' + conversationId);
} catch (e) {
  console.error('Memory save failed:', e.message);
}

return [{ json: ctx }];

const ctx = $input.item.json;
const siteId = ctx.site?.uuid;
